const before = (await chrome.tabs.query({})).map((t) => t.id);
await chrome.windows.create({ url: chrome.runtime.getURL('page.html?pop'), type: 'popup' });
await new Promise((r) => setTimeout(r, 1000));
const popout = (await chrome.tabs.query({})).find((t) => !before.includes(t.id));
await chrome.windows.remove(popout.windowId);
await new Promise((r) => setTimeout(r, 500));
const left = (await chrome.tabs.query({})).map((t) => t.id);
const again = await chrome.windows.remove(popout.windowId).then(() => 'closed', () => 'refused');
return JSON.stringify({ kept: JSON.stringify(left) === JSON.stringify(before), again });
